insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_tt3_v1'
from (values
('117.325.c.1.A',3,'A master electrician tells the crew to ''gang'' dimmers on one channel. In lighting vocabulary this means ___.','["Grouping several circuits to be controlled together", "Sewing a hem", "Painting a flat", "Printing a poster"]'::jsonb,0,'Ganging links circuits.','original'),
('117.325.c.1.A',3,'In costume vocabulary, a ''muslin'' is a ___.','["Kind of wig", "Inexpensive test garment used to check fit before cutting the final fabric", "Type of sound cable", "Stage floor finish"]'::jsonb,1,'Muslins are fitting prototypes.','original'),
('117.325.c.1.B',3,'A student explains that a ''rake'' is a stage floor that ___.','["Folds flat", "Lifts like an elevator", "Slopes upward away from the audience", "Rotates"]'::jsonb,2,'A raked stage tilts.','original'),
('117.325.c.1.B',3,'Counterweight fly systems let a crew member ___.','["Hold scenery by hand only", "Burn lines to drop it", "Lift scenery by throwing ropes", "Move heavy scenery with balanced weights and a rope lock"]'::jsonb,3,'Counterweights balance loads.','original'),
('117.325.c.1.C',3,'A designer builds a production calendar working backward from opening night. This helps to ___.','["Set deadlines for design, build and tech", "Cancel rehearsals", "Print tickets only", "Choose the cast"]'::jsonb,0,'Backward planning meets deadlines.','original'),
('117.325.c.1.C',3,'During a ''cue-to-cue'' rehearsal, the team ___.','["Strikes the set", "Skips to each technical cue to test and adjust it", "Auditions new actors", "Reads the whole play aloud"]'::jsonb,1,'Cue-to-cue focuses on technical transitions.','original'),
('117.325.c.1.D',3,'A student models shop safety by wearing hearing protection near a planer and ___.','["Wearing open sandals", "Working without instruction", "Tying back long hair and removing loose jewelry", "Leaving the guard off"]'::jsonb,2,'Personal safety includes clothing choices.','original'),
('117.325.c.1.D',3,'Which action models fire safety in a theatre?','["Blocking the fire exit", "Disabling the alarm", "Storing paint rags in a pile", "Using flame-retardant materials and keeping extinguishers accessible"]'::jsonb,3,'Fire safety requires planning.','original'),
('117.325.c.1.E',3,'A student creates a scene-by-scene breakdown listing each prop, light cue and sound cue. She is ___.','["Applying script analysis to technical needs", "Selling tickets", "Choosing seats", "Writing a review"]'::jsonb,0,'A breakdown organizes requirements.','original'),
('117.325.c.1.E',3,'A script says ''The room slowly fills with fog.'' The student marks this for ___.','["Programs", "Special effects and possibly the lighting department", "Ushers", "Box office"]'::jsonb,1,'Fog affects lighting and safety.','original'),
('117.325.c.2.A',3,'For a Greek tragedy performed on a bare stage with masks, which technical element carries much of the style?','["Revolving scenery", "Heavy fog only", "Mask and costume design", "Digital video wall"]'::jsonb,2,'Style determines focus.','original'),
('117.325.c.2.A',3,'For a futuristic science-fiction play, which technical choice supports the genre?','["Candles and wood", "Plain curtains", "Only a spotlight", "Metallic scenery, cool lighting and electronic sound"]'::jsonb,3,'Elements reinforce genre.','original'),
('117.325.c.2.B',3,'At the ''incubation/selection'' stage, a designer ___.','["Sketches possible ideas and chooses the strongest concept", "Cleans the shop", "Strikes the show", "Sells ads"]'::jsonb,0,'Ideas are developed and one is chosen.','original'),
('117.325.c.2.B',3,'After implementation, a designer evaluates the design by ___.','["Ignoring feedback", "Reviewing how well it served the production and noting improvements", "Hiding results", "Skipping tech"]'::jsonb,1,'Evaluation closes the loop.','original'),
('117.325.c.2.C',3,'A scenic designer uses vertical lines in a courthouse set to suggest ___.','["Weakness", "Chaos", "Height, strength or formality", "Silliness"]'::jsonb,2,'Vertical lines convey stature.','original'),
('117.325.c.2.C',3,'The principle of ''position'' in design refers to ___.','["The price of the set", "The cast size", "The time of the play", "Where an element is placed on stage"]'::jsonb,3,'Placement affects focus.','original'),
('117.325.c.2.D',3,'A designer varies the heights of platforms so the stage picture is interesting. This is ___.','["Variation", "Monotony", "Duplication", "Unity only"]'::jsonb,0,'Variation adds interest.','original'),
('117.325.c.2.D',3,'A symmetrical set with matching panels on each side shows ___.','["Rhythm only", "Formal balance", "Chaos", "Random layout"]'::jsonb,1,'Symmetry gives formal balance.','original'),
('117.325.c.2.E',3,'A lighting designer puts a blue gel on a warm amber light. The result will be ___.','["A brighter white", "A pure red", "A muted, darker color because the gel absorbs some light", "No change"]'::jsonb,2,'Filters subtract wavelengths.','original'),
('117.325.c.2.E',3,'The three primary colors of light are ___.','["Black, white and gray", "Cyan, magenta and yellow", "Red, yellow and blue", "Red, green and blue"]'::jsonb,3,'Additive primaries are RGB.','original'),
('117.325.c.2.F',3,'A technical director coordinates the build schedule, the designers'' needs and the crew''s skills. He is ___ the team.','["Managing", "Confusing", "Ignoring", "Dismissing"]'::jsonb,0,'Managers coordinate teams.','original'),
('117.325.c.2.F',3,'Which behavior supports effective teamwork in a production team?','["Blaming others", "Clear communication and respect for deadlines", "Keeping secrets", "Missing meetings"]'::jsonb,1,'Communication and reliability.','original'),
('117.325.c.2.G',3,'A student writes that leadership helps a crew stay organized, safe and motivated. She is ___ it.','["Hiding", "Ignoring", "Defending the importance of", "Rejecting"]'::jsonb,2,'Defending means supporting with reasons.','original'),
('117.325.c.2.G',3,'Which is a sign of strong leadership on a crew?','["Taking all the credit", "Avoiding tasks", "Ignoring questions", "Sharing credit and helping teammates solve problems"]'::jsonb,3,'Leaders support teams.','original'),
('117.325.c.2.H',3,'A student paints a surprising texture on a prop that suits the character. She is developing ___.','["Creativity and personal expression", "Imitation only", "Neglect", "Plagiarism"]'::jsonb,0,'Original choices express creativity.','original'),
('117.325.c.2.H',3,'Which approach helps a designer develop creativity?','["Refusing feedback", "Experimenting with materials and sketching many ideas", "Avoiding research", "Copying the first idea"]'::jsonb,1,'Exploration builds creativity.','original'),
('117.325.c.2.I',3,'A director gives the designer a mood board and a copy of the script with notes. The designer is ___ technical theatre documents.','["Burning", "Erasing", "Interpreting", "Selling"]'::jsonb,2,'Interpreting means understanding the intent.','original'),
('117.325.c.2.I',3,'A set designer draws a ground plan showing the stage from above. This document helps the crew ___.','["Print programs", "Choose music", "Cast the play", "Place walls, doors and platforms correctly"]'::jsonb,3,'Ground plans show layout.','original'),
('117.325.c.2.J',3,'A drafter uses a scale of 1/2 inch = 1 foot. A 16-foot-wide set will be ___ on the drawing.','["8 inches", "16 inches", "4 inches", "32 inches"]'::jsonb,0,'16 × 1/2 = 8.','original'),
('117.325.c.2.J',3,'A carpenter needs to cut a board to 5 feet 6 inches. How many total inches is that?','["72", "66", "56", "60"]'::jsonb,1,'5 × 12 + 6 = 66.','original'),
('117.325.c.3.A',3,'Before using a router in the shop, a trained student should ___.','["Wear loose sleeves", "Remove the guard", "Secure the work piece, set the bit depth and wear eye and ear protection", "Hold the piece loosely"]'::jsonb,2,'Specialized tools need setup and PPE.','original'),
('117.325.c.3.A',3,'Which material requires a respirator to use safely?','["Plain water", "Fabric swatches", "Paper tickets", "Spray paint and some adhesives with fumes"]'::jsonb,3,'Fumes require protection.','original'),
('117.325.c.3.C',3,'The master carpenter in a theatre ___.','["Leads the construction of scenery", "Sells tickets", "Calls cues", "Selects music"]'::jsonb,0,'Carpenters build the sets.','original'),
('117.325.c.3.C',3,'A costume shop manager typically ___.','["Paints flats", "Supervises costume construction, fittings and care", "Mixes sound", "Hangs lights"]'::jsonb,1,'Costume managers lead wardrobe work.','original'),
('117.325.c.3.D',3,'A student creates a light plot and a channel hookup. These documents tell the crew ___.','["Where to park", "How tickets are priced", "Where instruments hang and how they are patched", "Who is in the cast"]'::jsonb,2,'Plots and hookups guide the electricians.','original'),
('117.325.c.3.D',3,'A student interprets a costume plot to find ___.','["Gel colors only", "Dimmer levels", "Scene shop budget", "Which costume pieces each character wears in each scene"]'::jsonb,3,'Plots track costume use.','original'),
('117.325.c.3.B.i',3,'A student designing a set for a two-story house must plan for ___.','["Structural support and safe access for actors", "No supports", "No access", "Decorations only"]'::jsonb,0,'Safety and structure matter.','original'),
('117.325.c.3.B.i',3,'What does ''stock'' scenery refer to?','["Scenery thrown away", "Standard pieces such as flats and platforms that can be reused", "Scenery made of paper", "Scenery borrowed from space"]'::jsonb,1,'Stock scenery is reusable.','original'),
('117.325.c.3.B.ii',3,'A costume designer picks fabric with ''drape'' for a flowing gown because it ___.','["Reflects light like a mirror", "Never moves", "Hangs and moves gracefully", "Stands stiff"]'::jsonb,2,'Drape affects movement.','original'),
('117.325.c.3.B.ii',3,'When pulling a costume from stock, the first step is to ___.','["Dye it", "Cut it", "Burn it", "Check it against the actor''s measurements and the design"]'::jsonb,3,'Stock pieces need fitting.','original'),
('117.325.c.3.B.iii',3,'Ohm''s law relates voltage, current and ___.','["Resistance", "Position", "Rhythm", "Color"]'::jsonb,0,'V = I × R.','original'),
('117.325.c.3.B.iii',3,'A 1,000-watt instrument on a 120-volt circuit draws about how much current?','["120 amps", "8.3 amps", "0.12 amps", "1,000 amps"]'::jsonb,1,'1000 ÷ 120 ≈ 8.3.','original'),
('117.325.c.3.B.iv',3,'Sound travels as a ___.','["Stack of paper", "Stream of heat", "Wave of vibrations through a medium such as air", "Beam of light"]'::jsonb,2,'Sound is a mechanical wave.','original'),
('117.325.c.3.B.iv',3,'A hard, bare wall in a theatre tends to ___ sound.','["Erase", "Absorb completely", "Heat", "Reflect"]'::jsonb,3,'Hard surfaces reflect sound.','original'),
('117.325.c.3.B.v',3,'A marketing designer picks a bold image, readable type and clear dates for a poster. She is ___ a marketing product.','["Designing", "Scrapping", "Hiding", "Burning"]'::jsonb,0,'Posters need clear design.','original'),
('117.325.c.3.B.v',3,'Which element must appear on a poster for a school play?','["Props list", "Title, date, time and location", "Lighting hookups", "Cast shoe sizes"]'::jsonb,1,'Audiences need the basics.','original'),
('117.325.c.3.B.vi',3,'A stage manager records blocking in the promptbook using ___.','["Paint", "Glue", "Pencil notations that can be changed", "Permanent marker"]'::jsonb,2,'Blocking changes in rehearsal.','original'),
('117.325.c.3.B.vi',3,'When calling cues, the stage manager says ''Go'' to ___.','["Start intermission", "Raise house lights", "Seat the audience", "Tell the operator to execute the cue"]'::jsonb,3,'''Go'' triggers the cue.','original'),
('117.325.c.3.B.vii',3,'A scenic artist uses a sponge to apply layers of color for a stone effect. This is called ___.','["Sponging or stippling", "Embroidery", "Welding", "Rigging"]'::jsonb,0,'Sponging creates texture.','original'),
('117.325.c.3.B.vii',3,'To refine a painting technique, a scenic artist should ___.','["Paint without testing", "Test it on a sample board and adjust before painting the final piece", "Skip the base coat", "Use only one color"]'::jsonb,1,'Samples reduce errors.','original'),
('117.325.c.3.B.viii',3,'A prop designer creates a lightweight ''foam'' sword for a fight scene. The reason is ___.','["To save paint", "To make noise", "Safety for performers", "To hide the blade"]'::jsonb,2,'Safe props protect actors.','original'),
('117.325.c.3.B.viii',3,'A prop that an actor uses on stage is called a ___ prop.','["Floor only", "Costume", "Curtain", "Hand or practical"]'::jsonb,3,'Hand props are used by actors.','original'),
('117.325.c.4.A',3,'A designer researching an African village scene studies architecture, textiles and symbols from that culture. This shows ___.','["Working knowledge of cultural accuracy", "Guessing", "Mockery", "Ignoring the setting"]'::jsonb,0,'Research ensures accuracy.','original'),
('117.325.c.4.A',3,'If a play is set in the 1960s, which research source is most helpful?','["Modern cartoons", "Photographs, magazines and museum collections from that time", "A fantasy novel", "A cookbook"]'::jsonb,1,'Primary sources give accuracy.','original'),
('117.325.c.4.B',3,'A student synthesizes that streaming and film editing have changed expectations of pacing in theatre. She is ___ the impact of media.','["Deleting", "Copying", "Combining information to explain", "Ignoring"]'::jsonb,2,'Synthesis connects ideas.','original'),
('117.325.c.4.B',3,'Which is an effect of electronic media on theatre marketing?','["Tickets became free", "Posters were banned", "Audiences disappeared", "Online trailers and social media promote shows"]'::jsonb,3,'Media expands marketing.','original'),
('117.325.c.4.C',3,'The Chinese Peking Opera uses elaborate makeup and costumes. It is an example of ___.','["Cultural heritage in world theatre", "A modern musical", "A silent film", "Greek tragedy"]'::jsonb,0,'World theatre has many traditions.','original'),
('117.325.c.4.C',3,'Which key figure is associated with Italian commedia dell''arte masks?','["Antigone", "Harlequin", "Hamlet", "Macbeth"]'::jsonb,1,'Harlequin is a commedia character.','original'),
('117.325.c.4.D',3,'The Elizabethan playhouse such as the Globe featured ___.','["A proscenium arch with fly loft", "A film screen", "An open-air thrust stage with galleries", "An arena with no stage"]'::jsonb,2,'The Globe was thrust-style.','original'),
('117.325.c.4.D',3,'The invention of the proscenium arch during the Renaissance allowed designers to use ___.','["Only candles", "No scenery", "Only masks", "Painted perspective scenery"]'::jsonb,3,'Proscenium theatres favored perspective sets.','original'),
('117.325.c.4.E',3,'The progression of lighting from limelight to electric to LED shows how technology has ___ theatre.','["Changed", "Ended", "Frozen", "Reversed"]'::jsonb,0,'Technology evolves.','original'),
('117.325.c.4.E',3,'Which development made stage fog and haze safer and more controllable?','["Smoke pots", "Modern water-based fog machines", "Burning leaves", "Open flames"]'::jsonb,1,'Safer devices reduce risk.','original'),
('117.325.c.4.F',3,'A student analyzes plays by Wilson, Hansberry and Miranda to see how different cultures have shaped American theatre. She is analyzing ___.','["A fictional tradition", "A foreign tradition only", "The multicultural heritage of US theatre", "A single tradition"]'::jsonb,2,'U.S. theatre is multicultural.','original'),
('117.325.c.4.F',3,'August Wilson is known for plays about ___.','["Space travel", "Ancient Rome", "Medieval knights", "African American life across the twentieth century"]'::jsonb,3,'Wilson wrote the Pittsburgh Cycle.','original'),
('117.325.c.4.G',3,'The Group Theatre and the Federal Theatre Project were important in ___.','["Developing American theatre in the 1930s", "The Renaissance", "Ancient Greece", "Roman times"]'::jsonb,0,'They shaped US theatre history.','original'),
('117.325.c.4.G',3,'Which American designer is known for pioneering stage lighting design in the twentieth century?','["Claude Monet", "Jean Rosenthal", "Vincent van Gogh", "Pablo Picasso"]'::jsonb,1,'Rosenthal advanced lighting design.','original'),
('117.325.c.5.A',3,'A resume for a technical theatre applicant should be ___.','["Full of jokes", "Long and unfocused", "Organized, accurate and concise", "Handwritten on napkins"]'::jsonb,2,'Professionals value clarity.','original'),
('117.325.c.5.A',3,'A portfolio should show ___.','["Random papers", "Only one photo", "Unrelated art", "A range of design and build work with clear labels"]'::jsonb,3,'Variety and clarity.','original'),
('117.325.c.5.B',3,'Backstage during a quiet scene, a crew member should ___.','["Move silently and follow the stage manager''s instructions", "Chat loudly", "Run", "Use a flashlight carelessly"]'::jsonb,0,'Quiet professionalism.','original'),
('117.325.c.5.B',3,'If a cue is missed, a technician should ___.','["Hide", "Stay calm, tell the stage manager and follow instructions", "Panic", "Leave"]'::jsonb,1,'Calm communication keeps the show safe.','original'),
('117.325.c.5.C',3,'A student applies design elements such as color and line and then judges how well they served the story. She is evaluating herself as a ___.','["Cashier", "Visitor", "Creative artist", "Spectator only"]'::jsonb,2,'Self-evaluation as an artist.','original'),
('117.325.c.5.C',3,'Reviewing photos of a finished set and comparing them to the original sketches helps a designer ___.','["Discard the photos", "Hide the sketch", "Avoid learning", "Learn what to improve next time"]'::jsonb,3,'Comparison guides growth.','original'),
('117.325.c.5.D',3,'After a design presentation, a peer says: ''The color choices are strong; consider a more durable surface for the platform.'' This is ___.','["Constructive feedback", "Rumor", "Spam", "Insult"]'::jsonb,0,'Positive and specific.','original'),
('117.325.c.5.D',3,'When giving constructive criticism, you should ___.','["Be rude", "Be specific, respectful and offer a suggestion", "Be vague", "Be silent"]'::jsonb,1,'Helpful feedback has suggestions.','original'),
('117.325.c.5.E',3,'A review that notes how the crew''s quick scene changes kept the pace tight is ___.','["Vague", "Silly", "Specific and precise", "Unrelated"]'::jsonb,2,'Details support the claim.','original'),
('117.325.c.5.E',3,'Which sentence evaluates sound design precisely?','["I heard stuff", "Sound was there", "It was noisy", "The low rumble under the ghost scene increased the tension"]'::jsonb,3,'Precise observations name the effect.','original'),
('117.325.c.5.F',3,'A student compares the costume design of a period film to a stage play. She is evaluating ___.','["Two media with precise observations", "The weather", "The ticket", "The parking"]'::jsonb,0,'Cross-media evaluation.','original'),
('117.325.c.5.F',3,'Which comment about a TV show''s lighting is most specific?','["I liked it", "The flickering blue light suggested a hospital at night", "It was dark", "It looked good"]'::jsonb,1,'Specific details.','original'),
('117.325.c.5.G',3,'A student articulates that technical theatre skills open careers in film, TV, concerts and theme parks. She is ___ opportunities.','["Closing", "Denying", "Describing", "Hiding"]'::jsonb,2,'Articulating means explaining.','original'),
('117.325.c.5.G',3,'Which is an avocational opportunity in technical theatre?','["Quitting", "Selling cars only", "Ignoring theatre", "Volunteering on the crew of a community theatre"]'::jsonb,3,'Avocational means pursued for enjoyment.','original'),
('117.325.c.5.H',3,'A student explains that the safety habits she learned in the shop will help her in a future engineering or construction career. She is ___ theatre to careers.','["Connecting", "Hiding", "Ignoring", "Burning"]'::jsonb,0,'She links skills to careers.','original'),
('117.325.c.5.H',3,'Which skill from technical theatre helps in many fields?','["Ignoring plans", "Meeting deadlines and working in a team", "Skipping steps", "Avoiding teamwork"]'::jsonb,1,'These skills transfer.','original'),
('117.325.c.5.I',3,'A student creates a short video that explains how her team built a revolving set. She is using ___ to communicate findings.','["A saw", "A ladder", "Technology", "A hammer"]'::jsonb,2,'Video presents work.','original'),
('117.325.c.5.I',3,'A clear digital presentation of a design project has ___.','["Random order", "Unlabeled files", "Blank slides", "Labeled drawings, photos and concise explanations"]'::jsonb,3,'Clarity helps audiences.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
